preConditionHook:
// THE MICRO TREND LINE, MicroTrendLineFailedBreakout's construction unchanged:
// the two most recent CONFIRMED swing pivots, the bull line across the lows
// and the bear line across the highs, TLValue's FIRST-anchor two-point
// projection, read at microSwingStrength 1 and with the two anchors no more
// than microLineBars apart. That span test is what makes the line a MICRO line
// rather than the swing line.
//
// THIS RULE: the RECLAIM is the trigger. A bar within the last
// failureWindowBars traded THROUGH the line -- for a long, a bar whose low
// printed below the bull micro line -- and THIS bar closes back on the
// original side of the LINE. Grimes's span is 1 to 3 bars and Brooks's 2 to
// 10; microLineBars 5 splits them, failureWindowBars 3 is Grimes's.
//
// NOT MicroTrendLineFailedBreakout, which needs the closing price to clear the
// POKING BAR's own opposite extreme -- a higher bar than the line. This asks
// only for a close back on the right side of the line, so it fires on strictly
// more bars. Two rules until someone measures that they coincide.
//
// THE POKE IS NOT REQUIRED TO BE THE MOST RECENT ONE -- any bar in the window
// arms the reclaim, so the loop sets a flag rather than keeping the first hit.
// That is the difference in machinery from MicroTrendLineFailedBreakout, which
// must remember the poking bar's extreme.
//
// KEPT WHOLE like a crossing: the break and the recovery are tested on
// DIFFERENT bars, and every entry pane evaluates on the same bar, so no
// pane-AND reaches it.
//
// The pivot scan is INLINED rather than reaching into SwingHigh.json -- rules
// in this corpus never reference each other -- and mirrors the twin's
// SwingLow / SwingLowBar / SwingHigh / SwingHighBar at Occurrence 1 and 2.
// MEASURED, EL_Swing_Probe.txt / el_swing_output1.txt (@ES 60 min): the pivot
// test is MIXED -- AT OR ABOVE the microSwingStrength OLDER bars, STRICTLY
// ABOVE the microSwingStrength NEWER bars -- so a flat top yields exactly one
// pivot, the later of the equal bars; bars-ago indexing makes the SMALLER
// index the NEWER bar, so the strict half is the k < j loop. The confirmation
// lag is exactly microSwingStrength bars -- ONE bar here, the minimum that is
// still lookahead-safe. pivotLookback is EL's Length (offsets
// 0..pivotLookback-1 inclusive) and the neighbourhood test reaches
// microSwingStrength bars PAST the window, so the deepest index the scan
// touches is pivotLookback - 1 + microSwingStrength. A window with no pivot
// returns the -1 SENTINEL, guarded here on the BAR INDEX and never on a price.
// Occurrence 3+ is UNMEASURED and never asked for. The comparisons carry the
// 2.22e-12 relational tolerance. No WFSafe_SwingHigh exists, so plain EL
// governs.
//
// MEASURED, EL_TLValue_Probe.txt: the two-point line anchored at the FIRST
// pair, Slope = (P2 - P1) / (B2 - B1); value = P1 + (target - B1) * Slope,
// extrapolating freely, so it can be read at an older bar of the window.
// Bars-ago convention, OLDER pivot as P1/B1 (the zero-drift spelling).
// Bar1 = Bar2 silently returns 0.0 and is GUARDED rather than relied on; the
// slope is hoisted out of the per-target arithmetic where the twin recomputes
// it inside each TLValue call -- identical doubles, same line -- and is
// computed only inside the guard.
//
// THE PIVOTS ARE THE CURRENT ONES, not the pivots as they stood at bar kk; the
// line is re-read at each bar of the window through TLValue's free
// extrapolation, as ChannelLineBreakoutFailure and TrendLineBrokenRecently do.
//
// Scratch is declared in localVariables, not at hook scope: the generator only
// prefixes declared locals, so a hook-scope declaration is a redefinition when
// this rule is placed twice in one strategy. Every one is fully assigned each
// bar before it is read.
//
// Deepest bar touched:
// max(pivotLookback - 1 + microSwingStrength, failureWindowBars).
pivS = (int)microSwingStrength;
pivW = (int)pivotLookback;
loP1 = -1.0;
loB1 = -1.0;
loP2 = -1.0;
loB2 = -1.0;
foundLo = 0;
for (int j = pivS; j <= pivW - 1; ++j) {
    bool ok = true;
    for (int k = j - pivS; k < j; ++k) {
        if (!el_lt(low[j], low[k])) { ok = false; break; }
    }
    if (ok) {
        for (int k = j + 1; k <= j + pivS; ++k) {
            if (!el_le(low[j], low[k])) { ok = false; break; }
        }
    }
    if (ok) {
        ++foundLo;
        if (foundLo == 1) { loP2 = low[j]; loB2 = (double)j; }
        else { loP1 = low[j]; loB1 = (double)j; break; }
    }
}
hiP1 = -1.0;
hiB1 = -1.0;
hiP2 = -1.0;
hiB2 = -1.0;
foundHi = 0;
for (int j = pivS; j <= pivW - 1; ++j) {
    bool ok = true;
    for (int k = j - pivS; k < j; ++k) {
        if (!el_gt(high[j], high[k])) { ok = false; break; }
    }
    if (ok) {
        for (int k = j + 1; k <= j + pivS; ++k) {
            if (!el_ge(high[j], high[k])) { ok = false; break; }
        }
    }
    if (ok) {
        ++foundHi;
        if (foundHi == 1) { hiP2 = high[j]; hiB2 = (double)j; }
        else { hiP1 = high[j]; hiB1 = (double)j; break; }
    }
}
haveLoLine = (foundLo == 2) && (loB1 != loB2) && el_le(loB1 - loB2, microLineBars);
haveHiLine = (foundHi == 2) && (hiB1 != hiB2) && el_le(hiB1 - hiB2, microLineBars);
loSlope = 0.0;
hiSlope = 0.0;
if (haveLoLine) loSlope = (loP2 - loP1) / (loB2 - loB1);
if (haveHiLine) hiSlope = (hiP2 - hiP1) / (hiB2 - hiB1);
brokeLo = false;
brokeHi = false;
if (el_ge(failureWindowBars, 1.0)) {
    for (int kk = 1; kk <= (int)failureWindowBars; ++kk) {
        if (haveLoLine && el_lt(low[kk], loP1 + ((double)kk - loB1) * loSlope)) {
            brokeLo = true;
        }
        if (haveHiLine && el_gt(high[kk], hiP1 + ((double)kk - hiB1) * hiSlope)) {
            brokeHi = true;
        }
    }
}
lineNowLo = 0.0;
lineNowHi = 0.0;
if (haveLoLine) lineNowLo = loP1 + (0.0 - loB1) * loSlope;
if (haveHiLine) lineNowHi = hiP1 + (0.0 - hiB1) * hiSlope;
